from google.cloud import speech
from speech_client import get_speech_client
from speech_models import TranscriptionJob

def poll_transcription(job_id: str) -> TranscriptionJob:
    client = get_speech_client()
    operation = client.get_operation(name=job_id)

    if operation.done:
        response = operation.result()
        transcript = " ".join([result.alternatives[0].transcript for result in response.results])
        return TranscriptionJob(
            job_id=job_id,
            status="COMPLETED",
            transcript=transcript,
        )
    else:
        return TranscriptionJob(job_id=job_id, status="IN_PROGRESS")

from google.cloud import translate_v2 as translate
from speech_models import TranslationRequest, TranslationResult

def translate_transcript(request: TranslationRequest) -> TranslationResult:
    client = translate.Client()
    result = client.translate(
        request.text,
        target_language=request.target_language_code,
        source_language=request.source_language_code,
    )
    return TranslationResult(
        translated_text=result["translatedText"],
        detected_language_code=result.get("detectedSourceLanguage"),
    )

from google.cloud import dlp_v2 as dlp
from speech_models import ModerationRequest, ModerationResult

def moderate_transcript(request: ModerationRequest, project_id: str) -> ModerationResult:
    client = dlp.DlpServiceClient()
    # Construct the `inspect_config` to specify the types of content to scan
    # For moderation, we can use built-in info types or custom ones.
    # Here, we'll use a few common ones as an example.
    inspect_config = {
        "info_types": [
            {"name": "EMAIL_ADDRESS"},
            {"name": "PHONE_NUMBER"},
            {"name": "CREDIT_CARD_NUMBER"},
            {"name": "US_SOCIAL_SECURITY_NUMBER"},
        ],
        "include_quote": True,
    }

    # Optionally, you can add custom dictionaries for specific inappropriate words
    # For simplicity, we'll stick to built-in info types for now.

    # The item to be inspected.
    item = {"value": request.text}

    # Convert the project id into a full resource name.
    parent = f"projects/{project_id}"

    response = client.inspect_content(request={
        "parent": parent,
        "inspect_config": inspect_config,
        "item": item,
    })

    findings = response.result.findings
    is_safe = True
    scores = {"matches_found": len(findings)}

    if findings:
        is_safe = False

    return ModerationResult(is_safe=is_safe, scores=scores)

import os
from google.cloud import aiplatform
from vertexai.preview.generative_models import GenerativeModel, Part, Image
from speech_models import SummarizationRequest, SummarizationResult

def archive_summary(request: SummarizationRequest, project_id: str, location: str = "us-central1") -> SummarizationResult:
    aiplatform.init(project=project_id, location=location)
    model = GenerativeModel("gemini-pro") # Using gemini-pro for text generation

    prompt = f"Summarize the following text:\n\n{request.text}\n\nSummary:"

    response = model.generate_content(
        contents=[Part.from_text(prompt)],
        generation_config={
            "max_output_tokens": request.max_output_tokens,
        }
    )

    return SummarizationResult(summary=response.text)
